(function() {
  const ratioSlider = document.getElementById('bad-task-ratio');
  const ratioNumber = document.getElementById('bad-task-ratio-num');
  const gdpDisplay = document.getElementById('gdp-growth-display');
  const welfareDisplay = document.getElementById('welfare-loss-display');
  const coeffDisplay = document.getElementById('coeff-display');

  // Constants from paper
  const WELFARE_LOSS_COEFF = -19 / 53; // Approx -0.358
  const COEFF_DISPLAY_VALUE = -0.36;

  function updateCalculations(ratio) {
    const ratioDecimal = ratio / 100;

    // GDP growth is simply the ratio (as these tasks add to GDP)
    const gdpGrowth = ratio;

    // Welfare loss calculation: Ratio * Coefficient
    const welfareLoss = ratioDecimal * WELFARE_LOSS_COEFF * 100;

    // Update UI
    gdpDisplay.textContent = `+${gdpGrowth.toFixed(2)}%`;

    // Format welfare loss (ensure negative sign is visible)
    const formattedWelfare = welfareLoss < 0 ? welfareLoss.toFixed(2) : `+${welfareLoss.toFixed(2)}`;
    welfareDisplay.textContent = `${formattedWelfare}%`;

    // Update data attribute for acceptance interface if needed
    const container = document.getElementById('bad-tasks-welfare');
    if(container) {
        container.dataset.welfareLoss = welfareLoss.toFixed(4);
        container.dataset.gdpGrowth = gdpGrowth.toFixed(4);
    }
  }

  function syncInputs(source) {
    if (source === 'slider') {
      ratioNumber.value = ratioSlider.value;
    } else {
      ratioSlider.value = ratioNumber.value;
    }
    updateCalculations(parseFloat(ratioSlider.value));
  }

  // Event Listeners
  ratioSlider.addEventListener('input', () => syncInputs('slider'));
  ratioNumber.addEventListener('input', () => syncInputs('number'));

  // Initialize
  updateCalculations(parseFloat(ratioSlider.value));

  // Expose coefficient for display
  coeffDisplay.textContent = COEFF_DISPLAY_VALUE;

  // Keyboard accessibility for number input
  ratioNumber.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      ratioNumber.blur();
      syncInputs('number');
    }
  });
})();
